import datetime
import sys
from dateutil import rrule
from dateutil.relativedelta import relativedelta
from dateutil.rrule import DAILY, WEEKLY, MO, TU, WE, TH, FR
from dateutil.parser import parse
from dateutil.easter import easter

# Function to load calendars from sources
def load_calendars(sources):
    calendars = {}
    for source in sources:
        try:
            with open(source) as f:
                calendars[source] = f.read().splitlines()
        except FileNotFoundError:
            print(f'Error: Calendar file {source} not found.', file=sys.stderr)
            sys.exit(2)
    return calendars

# Function to check if a day is closed
def is_closed(day, calendars):
    for _, closed_days in calendars.items():
        if day.strftime('%Y-%m-%d') in closed_days:
            return True
    return False

# Function to count business days between two dates
def count_business_days(start, end, calendars):
    if start > end:
        print('Error: Start date is after end date.', file=sys.stderr)
        sys.exit(2)
    business_days = 0
    for day in rrule(DAILY, dtstart=start, until=end):
        if not is_closed(day, calendars):
            business_days += 1
    return business_days

# Main function to handle command-line arguments
if __name__ == '__main__':
    if len(sys.argv) != 4:
        print('Usage: python bizdays.py <command> <start_date> <end_date>', file=sys.stderr)
        sys.exit(2)
    command = sys.argv[1]
    start_date = parse(sys.argv[2])
    end_date = parse(sys.argv[3])
    calendars = load_calendars(['data/closures.json', 'data/closures-2027.json'])
    if command == 'add':
        print(count_business_days(start_date, end_date, calendars))
    elif command == 'between':
        print(count_business_days(start_date, end_date, calendars))
    else:
        print('Error: Invalid command.', file=sys.stderr)
        sys.exit(2)
